from urllib.parse import urlencode

VALID_KINDS = {"anime", "manga", "music", "raw", "stage"}
IGNORED = {None, "", "all", "全部"}


def clean(value):
    if value in IGNORED:
        return ""
    value = str(value).strip()
    return "" if value in IGNORED else value


def positive_int(value, default):
    try:
        num = int(value)
        return num if num > 0 else default
    except (TypeError, ValueError):
        return default


def execute(node_id, node_data, context):
    kind = clean(context.get("kind")) or "anime"
    if kind not in VALID_KINDS:
        kind = "anime"

    params = {}
    keyword = clean(context.get("keyword"))
    if keyword:
        params["q"] = keyword
    if kind != "anime":
        params["kind"] = kind

    page_num = positive_int(context.get("page_num"), 1)
    if page_num > 1:
        params["page"] = page_num

    query = urlencode(params)
    context["anibt_kind"] = kind
    context["anibt_path"] = "/magnets" + (("?" + query) if query else "")

import html
import json
import re

KIND_LABELS = {
    "anime": "番剧",
    "manga": "漫画",
    "music": "音乐",
    "raw": "RAW",
    "stage": "舞台剧",
}
NAME_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_$-"


def text_of(markup):
    text = re.sub(r"<[^>]+>", "", markup or "")
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def skip_ref(text, pos):
    while pos < len(text) and text[pos].isspace():
        pos += 1
    if not text.startswith("$R[", pos):
        return pos
    end = text.find("]", pos)
    if end < 0:
        return pos
    cur = end + 1
    while cur < len(text) and text[cur].isspace():
        cur += 1
    if cur >= len(text) or text[cur] != "=":
        return pos
    cur += 1
    while cur < len(text) and text[cur].isspace():
        cur += 1
    return cur


def value_start(text, key, pos=0):
    marker = key + ":"
    while True:
        idx = text.find(marker, pos)
        if idx < 0:
            return -1
        if idx == 0 or text[idx - 1] not in NAME_CHARS:
            cur = idx + len(marker)
            while cur < len(text) and text[cur].isspace():
                cur += 1
            return skip_ref(text, cur)
        pos = idx + len(marker)


def balanced(text, start):
    pairs = {"{": "}", "[": "]"}
    close = pairs.get(text[start:start + 1])
    if not close:
        return "", start
    depth = 0
    in_string = False
    escaped = False
    for idx in range(start, len(text)):
        ch = text[idx]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch == text[start]:
            depth += 1
        elif ch == close:
            depth -= 1
            if depth == 0:
                return text[start:idx + 1], idx + 1
    return "", start


def json_string(text, start):
    escaped = False
    for idx in range(start + 1, len(text)):
        ch = text[idx]
        if escaped:
            escaped = False
        elif ch == "\\":
            escaped = True
        elif ch == '"':
            return json.loads(text[start:idx + 1]), idx + 1
    return "", start


def field(text, key, default=""):
    start = value_start(text or "", key)
    if start < 0 or start >= len(text):
        return default
    ch = text[start]
    if ch == '"':
        return json_string(text, start)[0]
    if ch in "[{":
        return balanced(text, start)[0]

    end = start
    while end < len(text) and text[end] not in ",}]\n":
        end += 1
    raw = text[start:end].strip()
    if raw in ("", "null", "void 0", "undefined"):
        return default
    try:
        return int(raw)
    except ValueError:
        return raw


def string_list(text, key):
    raw = field(text, key, "[]")
    return [json.loads('"' + m.group(1) + '"') for m in re.finditer(r'"((?:\\.|[^"\\])*)"', raw)]


def top_objects(array_raw):
    items = []
    pos = 0
    while True:
        start = (array_raw or "").find("{", pos)
        if start < 0:
            return items
        raw, pos = balanced(array_raw, start)
        if not raw:
            return items
        items.append(raw)


def release_cards(page_html):
    page_html = page_html or ""
    cards = {}
    patterns = [
        (r'data-testid="release-card"\s+data-release-id="([^"]+)"', '<div class="group relative'),
        (r'href="/other-release/([^"]+)"', '<article class="group relative'),
    ]
    for pattern, start_marker in patterns:
        matches = list(re.finditer(pattern, page_html))
        for idx, match in enumerate(matches):
            start = page_html.rfind(start_marker, 0, match.start())
            if start < 0:
                start = match.start()
            end = len(page_html)
            if idx + 1 < len(matches):
                next_start = page_html.rfind(start_marker, 0, matches[idx + 1].start())
                end = next_start if next_start > start else matches[idx + 1].start()
            cards.setdefault(match.group(1), page_html[start:end])
    return cards


def card_size(card):
    match = re.search(r">\s*(\d+(?:\.\d+)?\s*(?:B|KB|MB|GB|TB))\s*<", card or "")
    return match.group(1) if match else ""


def card_time(card):
    match = re.search(r"<time[^>]*>(.*?)</time>", card or "", re.S)
    return text_of(match.group(1)) if match else ""


def card_badges(card):
    values = []
    seen = set()
    for match in re.finditer(r'data-slot="badge"[^>]*>(.*?)</span>', card or "", re.S):
        value = text_of(match.group(1))
        if value and value not in seen:
            values.append(value)
            seen.add(value)
    return " · ".join(values)


def card_uploader(card):
    match = re.search(r'<span class="truncate">(.*?)</span>', card or "", re.S)
    return text_of(match.group(1)) if match else ""


def card_cover(card):
    match = re.search(r'<source[^>]+srcSet="([^"]+)"', card or "")
    if not match:
        return ""
    first = html.unescape(match.group(1)).split(",", 1)[0].strip()
    return first.split(" ", 1)[0]


def data_cover(item):
    cover = field(item, "animeCoverImage")
    webp = field(item, "animeCoverImageWebp")
    return field(cover, "large") or field(cover, "extraLarge") or field(webp, "url")


def snapshot(page_html, kind):
    key = "otherSnapshot" if kind in {"manga", "music", "raw", "stage"} else "snapshot"
    return field(page_html, key)


def execute(node_id, node_data, context):
    page_html = (context.get("response") or "").replace("\x00", "\\0")
    kind = context.get("anibt_kind") or "anime"
    if kind not in KIND_LABELS:
        kind = "anime"

    snap = snapshot(page_html, kind)
    cards = release_cards(page_html)
    items = []
    for item in top_objects(field(snap, "page", "[]")):
        release = field(item, "release")
        title = field(release, "title")
        if not title:
            continue

        release_id = str(field(release, "id") or field(release, "_id"))
        card = cards.get(release_id, "")
        release_kind = field(release, "category") or kind
        magnet = field(release, "magnetLink")

        items.append({
            "id": release_id,
            "title": title,
            "link": magnet or field(item, "torrentUrl"),
            "cover": card_cover(card) or data_cover(item),
            "size": card_size(card),
            "misc": card_badges(card),
            "category": KIND_LABELS.get(release_kind, str(release_kind)),
            "uploader": card_uploader(card),
            "uploaded_at": card_time(card),
        })

    context["search_result"] = {
        "total": field(snap, "totalCount", None),
        "totalPages": field(snap, "totalPages", None),
        "page": field(snap, "pageNumber", 1),
        "items": items,
    }
